const int S = 31; // after 30 inherited halvings every value is 0
int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    // Iterative DFS order from the root; process children before parents.
    vector<int> order, parent(n, -1);
    order.reserve(n);
    vector<int> st = {0};
    parent[0] = -1;
    vector<char> seen(n, 0);
    seen[0] = 1;
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        order.push_back(u);
        for (int w : adj[u]) if (!seen[w]) { seen[w] = 1; parent[w] = u; st.push_back(w); }
    }
    // childSum[u][s]: sum of children's best scores when s halvings were inherited.
    vector<long long> childSum((size_t)n * S, 0);
    long long dp[S];
    for (int idx = n - 1; idx >= 0; idx--) {
        int u = order[idx];
        long long *cs = &childSum[(size_t)u * S];
        for (int s = S - 1; s >= 0; s--)
            dp[s] = max((a[u] >> s) - k + cs[s], (a[u] >> (s + 1)) + cs[min(s + 1, S - 1)]);
        if (parent[u] < 0) { printf("%lld\n", dp[0]); return 0; }
        long long *ps = &childSum[(size_t)parent[u] * S];
        for (int s = 0; s < S; s++) ps[s] += dp[s];
    }
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static final int S = 31; // after 30 inherited halvings every value is 0

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int[] head = new int[n], nxt = new int[2 * n], to = new int[2 * n];
        java.util.Arrays.fill(head, -1);
        for (int i = 0, e = 0; i < n - 1; i++) {
            int u = nextInt(), v = nextInt();
            to[e] = v; nxt[e] = head[u]; head[u] = e++;
            to[e] = u; nxt[e] = head[v]; head[v] = e++;
        }
        // Iterative DFS order from the root; process children before parents.
        int[] order = new int[n], parent = new int[n], stack = new int[n];
        boolean[] seen = new boolean[n];
        int top = 0, cnt = 0;
        stack[top++] = 0;
        seen[0] = true;
        parent[0] = -1;
        while (top > 0) {
            int u = stack[--top];
            order[cnt++] = u;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (!seen[w]) { seen[w] = true; parent[w] = u; stack[top++] = w; }
            }
        }
        // childSum[u*S+s]: sum of children's best scores when s halvings were inherited.
        long[] childSum = new long[n * S];
        long[] dp = new long[S];
        for (int idx = n - 1; idx >= 0; idx--) {
            int u = order[idx], base = u * S;
            for (int s = S - 1; s >= 0; s--)
                dp[s] = Math.max((a[u] >> s) - k + childSum[base + s], (a[u] >> (s + 1)) + childSum[base + Math.min(s + 1, S - 1)]);
            if (parent[u] < 0) { System.out.println(dp[0]); return; }
            int pb = parent[u] * S;
            for (int s = 0; s < S; s++) childSum[pb + s] += dp[s];
        }
    }
}

