import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

const S = 31 // after 30 inherited halvings every value is 0

func main() {
	n, k := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	adj := make([][]int, n)
	for i := 0; i < n-1; i++ {
		u, v := readInt(), readInt()
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}
	// Iterative DFS order from the root; process children before parents.
	order := make([]int, 0, n)
	parent := make([]int, n)
	seen := make([]bool, n)
	parent[0] = -1
	seen[0] = true
	stack := []int{0}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, u)
		for _, w := range adj[u] {
			if !seen[w] {
				seen[w] = true
				parent[w] = u
				stack = append(stack, w)
			}
		}
	}
	// childSum[u*S+s]: sum of children's best scores when s halvings were inherited.
	childSum := make([]int, n*S)
	var dp [S]int
	for idx := n - 1; idx >= 0; idx-- {
		u := order[idx]
		cs := childSum[u*S : u*S+S]
		for s := S - 1; s >= 0; s-- {
			dp[s] = max((a[u]>>s)-k+cs[s], (a[u]>>(s+1))+cs[min(s+1, S-1)])
		}
		if parent[u] < 0 {
			fmt.Println(dp[0])
			return
		}
		ps := childSum[parent[u]*S : parent[u]*S+S]
		for s := 0; s < S; s++ {
			ps[s] += dp[s]
		}
	}
}
